mapper.select:
SELECT `id`, `tenant_id`, `task_type`, `aggregate_id`, `idempotency_key`, `payload_json`,
`state`, `attempts`, `max_attempts`, `available_at`, `locked_at`, `lease_token`,
`last_error`, `created_at`, `updated_at` FROM `taskoutbox` WHERE `id` =
#{id,jdbcType=CHAR,typeHandler=com.duozhi.outbound.common.dao.typehandler.UuidTypeHandler}
AND `tenant_id` = #{tenantId,jdbcType=INTEGER}

SELECT `id`, `tenant_id`, `task_type`, `aggregate_id`, `idempotency_key`, `payload_json`,
`state`, `attempts`, `max_attempts`, `available_at`, `locked_at`, `lease_token`,
`last_error`, `created_at`, `updated_at` FROM `taskoutbox`
WHERE `tenant_id` = #{tenantId,jdbcType=INTEGER}
ORDER BY `id` LIMIT #{limit,jdbcType=INTEGER} OFFSET #{offset,jdbcType=INTEGER}

SELECT * FROM taskoutbox FORCE INDEX (ix_taskoutbox_ready_scope) WHERE tenant_id = #{tenantId} AND task_type IN
#{type}
AND state='PROCESSING' AND locked_at <= #{cutoff} AND attempts >= max_attempts LIMIT 10

SELECT t.* FROM taskoutbox t FORCE INDEX(ix_taskoutbox_stream_scope) WHERE tenant_id=#{tenantId} AND aggregate_id IN
#{id}
AND task_type IN ('ai_turn','after_playback','interrupt_playback') AND state IN ('PENDING','FAILED') AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(IF(JSON_VALID(payload_json),payload_json,'{}'),'$.product_kind')),'')<>'appointment' AND EXISTS(SELECT 1 FROM callsession c WHERE c.tenant_id=t.tenant_id AND c.id=t.aggregate_id AND c.status IN ('COMPLETED','FAILED','NO_ANSWER','BUSY','VOICEMAIL') AND c.attempts=JSON_EXTRACT(IF(JSON_VALID(t.payload_json),t.payload_json,'{}'),'$.attempt')) ORDER BY t.id LIMIT 1000 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE taskoutbox SET locked_at=#{now},updated_at=#{now} WHERE tenant_id = #{tenantId} AND
id=#{id,typeHandler=com.duozhi.outbound.common.dao.typehandler.UuidTypeHandler} AND
state='PROCESSING' AND lease_token=#{lease} AND locked_at > #{cutoff}

